def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[-1][1] == 'D' else 'C'

    last_own, last_opp = history[-1]
    prev_own = history[-2][0]

    opp_def = 0
    own_def = 0
    for m, o in history:
        if m == 'D':
            own_def += 1
        if o == 'D':
            opp_def += 1
    total_def_rate = opp_def / float(n)

    w10 = 10 if n >= 10 else n
    def10 = 0
    for _, o in history[-w10:]:
        if o == 'D':
            def10 += 1
    rate10 = def10 / float(w10)

    w20 = 20 if n >= 20 else n
    def20 = 0
    for _, o in history[-w20:]:
        if o == 'D':
            def20 += 1
    rate20 = def20 / float(w20)

    start = max(1, n - 25)
    forgive = 0
    punished = 0
    exploited = 0
    coop = 0
    for i in range(start, n):
        po = history[i - 1][0]
        co = history[i][1]
        if po == 'D':
            if co == 'C':
                forgive += 1
            else:
                punished += 1
        else:
            if co == 'C':
                coop += 1
            else:
                exploited += 1

    bad = (exploited + 1.0) / (exploited + coop + 2.0)

    success_D = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'C':
        success_D += 1
        i -= 1

    if total_def_rate > 0.70 or rate20 > 0.60 or bad > 0.55:
        return 'D'

    if last_opp == 'C':
        if forgive > punished and forgive > 0:
            if rate10 > 0.40 or rate20 > 0.35 or bad > 0.45:
                return 'D'

            p = 0.35
            if punished == 0:
                p += 0.10
            if forgive >= 3:
                p += 0.10
            if success_D >= 2:
                p += 0.05
            if total_def_rate < 0.05:
                p += 0.20
            elif total_def_rate < 0.12:
                p += 0.10
            elif total_def_rate < 0.22:
                p += 0.05
            if n >= 70:
                p += 0.05
            if n >= 85:
                p += 0.10
            if n >= 94:
                p += 0.15
            if rate20 > 0.10:
                p -= 0.10
            if rate20 > 0.20:
                p -= 0.20
            if rate20 > 0.35:
                p -= 0.30
            if total_def_rate > 0.35:
                p -= 0.15
            if bad > 0.35:
                p -= 0.10
            if bad > 0.45:
                p -= 0.20

            if p < 0.0:
                p = 0.0
            if p > 0.95:
                p = 0.95

            if rng.random() < p:
                return 'D'
            return 'C'

        if rate10 > 0.35 or rate20 > 0.30 or bad > 0.35:
            return 'D'

        p = 0.03
        if total_def_rate < 0.03:
            p = 0.06
        elif total_def_rate < 0.10:
            p = 0.05
        elif total_def_rate < 0.20:
            p = 0.04

        if own_def == 0 and total_def_rate < 0.05:
            if n >= 85:
                p = max(p, 0.30)
            elif n >= 70:
                p = max(p, 0.15)
            elif n >= 50:
                p = max(p, 0.08)

        if n >= 60 and total_def_rate < 0.15 and rate20 < 0.15:
            p = max(p, 0.08)
        if n >= 82 and total_def_rate < 0.20 and rate20 < 0.20:
            p = max(p, 0.18)
        if n >= 92 and total_def_rate < 0.30:
            p = max(p, 0.55)

        if last_own == 'D' and forgive <= punished:
            p = 0.0

        if rng.random() < p:
            return 'D'
        return 'C'

    if prev_own == 'D':
        if rate10 >= 0.60 or rate20 >= 0.55 or total_def_rate >= 0.55 or bad > 0.55:
            return 'D'
        if total_def_rate > 0.35 and bad > 0.30:
            return 'D'
        if forgive > 0 or total_def_rate < 0.25:
            return 'C'
        return 'D'

    if last_own == 'D':
        if total_def_rate < 0.12 and def10 <= 1 and forgive > punished:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    if total_def_rate < 0.06 and def20 <= 1 and forgive > 0:
        if rng.random() < 0.15:
            return 'C'

    return 'D'
